-- Give the existing vocabulary the categories the mapper proposes for it.
--
-- Generated by running src/lib/barboraMapping.js over the household's 217
-- ingredients against the published catalogue, and reviewed one by one. Every
-- row here is an `exact` term match on Barbora's own category name, a reviewed
-- alias, or a retreat to a parent where the shop sells the thing in two
-- places. The remaining 151 ingredients keep their section's aisle link.
--
-- Idempotent, and it never touches a category a person chose by hand.

update public.ingredients ing set
  barbora_category_path = m.path,
  barbora_mapping_reason = m.reason,
  barbora_mapping_source = 'automatic',
  barbora_mapping_updated_at = now()
from (values
