  ('Batonas', '/duonos-gaminiai-ir-konditerija/duona', 'parent_fallback'),
  ('Duona', '/duonos-gaminiai-ir-konditerija/duona', 'exact'),
  ('Tortilijos', '/duonos-gaminiai-ir-konditerija/duona/tortilijos-ir-picu-paplociai', 'exact'),
